/**
 * Message framing — the CANONICAL on-the-wire envelope.
 *
 * A framed SyncPlay message is a flat JSON object:
 *
 *     { "type": "syncplay_...", "protocol_version": 1, "timestamp": 123, ...payload }
 *
 * The payload fields are spread at the TOP LEVEL of the object. This matches
 * what the PHP server reads (`$payload['member_id']`, `$payload['position']`,
 * ...) and what `Messages::*` factory methods produce.
 *
 * DEPRECATED: the Tizen client wraps sends as `{ type, data, timestamp }`,
 * nesting all fields under `data`. The server does NOT read `data`, so those
 * messages silently fail. That wrapper is deprecated and MUST NOT be used.
 * `decodeMessage` tolerates and unwraps it for backward compatibility ONLY
 * while the envelope lacks `protocol_version`: canonical frames always stamp
 * `protocol_version` (§1 item 4 of SPEC.md; the server's `Messages::frame`
 * stamps it literally), so for a frame carrying it, `data` is a legitimate
 * TOP-LEVEL payload field (e.g. `syncplay_info`, `Messages::info()`) and
 * survives decode UNTOUCHED (M-SYNCPLAY-02).
 */

import {
  isValidMessageType,
  PROTOCOL_VERSION,
  type RawMessage,
  type SyncPlayMessageType,
  type UnknownFrame,
} from './messages';

/**
 * A clock source, injected so the module stays pure and deterministic.
 *
 * CONTRACT: `now()` MUST return **epoch milliseconds** (the same scale as
 * `Date.now()`). The framing `timestamp` field is emitted in milliseconds and
 * `TimeSync`'s drift math presumes a ms clock (it converts via `now() / 1000`
 * to reach the server's per-second scale). Do NOT inject a seconds clock.
 *
 * A fractional ms clock (e.g. `performance.timeOrigin + performance.now()`) is
 * tolerated on the time-sync path: `SyncPlayClient` truncates the ping's
 * `client_time` (t1) and the pong's receive time (t4) to integer ms, because
 * the server int-casts the `client_time` it echoes (SPEC section 5).
 */
export type NowFn = () => number;

/**
 * Encode a message into the canonical RAW JSON object.
 *
 * The result is a plain object (NOT a JSON string) so the transport layer can
 * serialize it however it likes. Payload fields are spread at the top level;
 * `type` and `protocol_version` are always set; `timestamp` is taken from the
 * injected clock.
 *
 * @param type    A valid SyncPlay message type.
 * @param payload The message body (top-level fields).
 * @param now     Clock source for the `timestamp` field.
 */
export function encodeMessage(
  type: SyncPlayMessageType,
  payload: Record<string, unknown>,
  now: NowFn,
): RawMessage {
  return {
    ...payload,
    type,
    protocol_version: PROTOCOL_VERSION,
    timestamp: now(),
  };
}

/**
 * Decode an inbound message into a flat RawMessage.
 *
 * Accepts either a JSON string or an already-parsed object. Tolerates (and
 * unwraps) the deprecated Tizen `{ type, data, timestamp }` envelope ONLY when
 * the frame lacks a `protocol_version`: that wrapper never carries one, whereas
 * every canonical message does (§1 item 4), so a frame with `protocol_version`
 * is NOT the wrapper and its `data` — if present — is a legitimate top-level
 * payload field that must survive decode untouched. Pre-M-SYNCPLAY-02 the
 * heuristic keyed only on "an object `data` sits beside `type`", which
 * destructively hoisted-and-deleted `data` on canonical frames that legitimately
 * carry it (e.g. `syncplay_info`) and broke the "no mutation" promise that
 * `onUnknownFrame` makes to non-SyncPlay consumers.
 *
 * Returns `null` for anything that is not a JSON object carrying a string
 * `type`. A surviving frame whose `type` passes {@link isValidMessageType}
 * comes back as {@link RawMessage}; foreign vocabulary comes back as the
 * honest {@link UnknownFrame} — CONSOLIDATED m19 (review asphp MINOR-7): the
 * old blanket `as RawMessage` promised canonicity the decode never verified,
 * handing the `pending_command` lane compiler-false RawMessages. Since
 * S-syncplay-07 the branch runs through the exported {@link isCanonicalFrame}
 * predicate, so this function and its callers share one canonicity law.
 */
export function decodeMessage(raw: unknown): RawMessage | UnknownFrame | null {
  let obj: unknown = raw;

  if (typeof raw === 'string') {
    try {
      obj = JSON.parse(raw);
    } catch {
      return null;
    }
  }

  if (typeof obj !== 'object' || obj === null || Array.isArray(obj)) {
    return null;
  }

  const record = obj as Record<string, unknown>;

  if (typeof record.type !== 'string') {
    return null;
  }

  // Unwrap the deprecated Tizen { type, data, timestamp } envelope — and ONLY
  // that envelope. A frame carrying `protocol_version` (§1 item 4; the server's
  // Messages::frame stamps it on every canonical message) is NOT the wrapper, so
  // its `data`, if present, is a legitimate top-level payload field
  // (`syncplay_info`, `Messages::info()`) and MUST pass through UNTOUCHED
  // (M-SYNCPLAY-02). The wrapper never carries `protocol_version`, so the
  // tolerance for legacy Tizen sends is preserved exactly.
  //
  // SPY-S15 (watch note): this unwrap is presence-keyed on `protocol_version`;
  // the VALUE law (non-integer / higher-than-supported refused, absent and stale
  // integers tolerated) lives in client.ts handleIncoming (LW-049). Tightening
  // either side breaks the documented legacy tolerance — revise both together
  // under a future wire-law revision; no behavior change here.
  const data = record.data;
  const frame: Record<string, unknown> =
    !('protocol_version' in record) &&
    typeof data === 'object' &&
    data !== null &&
    !Array.isArray(data)
      ? (() => {
          const rest: Record<string, unknown> = {};
          for (const key of Object.keys(record)) {
            if (key !== 'data') {
              // S39 (phlix-syncplay-050): copy as an OWN inert data property,
              // never via [[Set]]. A JSON-parsed frame carries `__proto__` as an
              // OWN key, so `rest[key] = record[key]` invoked the
              // Object.prototype.__proto__ SETTER — swapping rest's prototype
              // and silently dropping the key (harmless only as long as the
              // trailing own-keys spread survives: fragile by construction).
              // defineProperty bypasses the setter and keeps the unwrap
              // byte-consistent with the canonical pass-through, which always
              // preserved such keys untouched.
              Object.defineProperty(rest, key, {
                value: record[key],
                enumerable: true,
                writable: true,
                configurable: true,
              });
            }
          }
          return { ...(data as Record<string, unknown>), ...rest };
        })()
      : record;

  // The canonicity check the return type always claimed (CONSOLIDATED m19),
  // asserted through the exported S-syncplay-07 predicate so callers narrow
  // without a receiver-side cast. RawMessage now types an un-stamped frame
  // honestly (WireEnvelope), so the positive branch carries no lie even for
  // legacy-wrapped frames without `protocol_version`.
  return isCanonicalFrame(frame) ? frame : (frame as UnknownFrame);
}

/**
 * Honest canonicity check (phlix-syncplay-007 / S-syncplay-07): a decoded
 * frame is a `RawMessage` exactly when its `type` is in the canonical
 * vocabulary — the same law {@link decodeMessage}'s branch has always
 * applied internally. Receivers should call THIS instead of casting a
 * `RawMessage | UnknownFrame` union to RawMessage.
 */
export function isCanonicalFrame(
  frame: { type: unknown } | Record<string, unknown>,
): frame is RawMessage {
  return typeof frame.type === 'string' && isValidMessageType(frame.type);
}

/** Serialize a raw message object to a JSON string for transmission. */
export function serializeMessage(message: RawMessage): string {
  return JSON.stringify(message);
}
